// Pointer-based card movement. Only a designated handle captures gestures, so
// scrolling and text editing elsewhere keep their native touch behaviour.
// Modal editors supply their own scroller and top-layer ghost parent; page
// consumers retain window scrolling and body overlays. Narrow multi-column
// boards can separately opt into horizontal edge scrolling during a drag.
export function attachCardDrag({root,itemSelector='[data-drag-id]',handleSelector='[data-drag-handle]',dropSelector='[data-drop-id]',scrollContainer=null,horizontalScrollContainer=null,ghostParent=null,onDrop}) {
  let active=null,scrollFrame;
  const mark=drop=>{root.querySelectorAll('.is-drop-target').forEach(el=>el.classList.remove('is-drop-target'));drop?.classList.add('is-drop-target');};
  const findDrop=event=>document.elementsFromPoint(event.clientX,event.clientY).map(el=>el.closest?.(dropSelector)).find(el=>el&&root.contains(el));
  const autoScroll=()=>{if(!active?.moved)return;const point=active.point,margin=72,bounds=scrollContainer?.getBoundingClientRect(),top=bounds?.top||0,bottom=bounds?.bottom||innerHeight;let delta=0;if(point.clientY<top+margin)delta=-Math.min(15,(top+margin-point.clientY)/margin*15);else if(point.clientY>bottom-margin)delta=Math.min(15,(point.clientY-(bottom-margin))/margin*15);const horizontalBounds=horizontalScrollContainer?.getBoundingClientRect();let horizontalDelta=0;if(horizontalBounds){const edge=Math.min(56,horizontalBounds.width/4);if(point.clientX<horizontalBounds.left+edge)horizontalDelta=-Math.min(15,(horizontalBounds.left+edge-point.clientX)/edge*15);else if(point.clientX>horizontalBounds.right-edge)horizontalDelta=Math.min(15,(point.clientX-(horizontalBounds.right-edge))/edge*15);}if(delta)(scrollContainer||window).scrollBy(0,delta);if(horizontalDelta)horizontalScrollContainer.scrollBy(horizontalDelta,0);if(delta||horizontalDelta)mark(findDrop(point));scrollFrame=requestAnimationFrame(autoScroll);};
  const clean=()=>{cancelAnimationFrame(scrollFrame);if(!active)return;active.ghost?.remove();active.item.classList.remove('is-dragging');try{active.handle.releasePointerCapture(active.pointerId);}catch{}active=null;mark(null);};
  const down=event=>{if(event.button!==0||active)return;const handle=event.target.closest(handleSelector),item=handle?.closest(itemSelector);if(!item||!root.contains(item)||handle.disabled)return;active={item,handle,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,rect:item.getBoundingClientRect(),point:{clientX:event.clientX,clientY:event.clientY},moved:false};try{handle.setPointerCapture(event.pointerId);}catch{}};
  const move=event=>{if(!active||event.pointerId!==active.pointerId)return;active.point={clientX:event.clientX,clientY:event.clientY};const dx=event.clientX-active.startX,dy=event.clientY-active.startY;if(!active.moved&&Math.hypot(dx,dy)<7)return;event.preventDefault();if(!active.moved){active.moved=true;active.item.classList.add('is-dragging');const ghost=active.item.cloneNode(true);ghost.removeAttribute('id');ghost.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));ghost.setAttribute('aria-hidden','true');ghost.inert=true;Object.assign(ghost.style,{position:'fixed',left:active.rect.left+'px',top:active.rect.top+'px',width:active.rect.width+'px',height:active.rect.height+'px',margin:'0',pointerEvents:'none',zIndex:'1000',opacity:'.94',boxShadow:'0 12px 35px color-mix(in srgb, var(--shadow-ink) 20.0%, transparent)'});(ghostParent||document.body).append(ghost);active.ghost=ghost;scrollFrame=requestAnimationFrame(autoScroll);}active.ghost.style.transform=`translate(${dx}px,${dy}px) rotate(1deg)`;mark(findDrop(event));};
  const up=event=>{if(!active||event.pointerId!==active.pointerId)return;const {item,moved,handle}=active,drop=moved?findDrop(event):null;clean();if(moved){const suppress=click=>{click.preventDefault();click.stopImmediatePropagation();};handle.addEventListener('click',suppress,{capture:true,once:true});setTimeout(()=>handle.removeEventListener('click',suppress,true),0);}if(drop)onDrop({itemId:item.dataset.dragId,dropId:drop.dataset.dropId,item,drop,event});};
  root.addEventListener('pointerdown',down);root.addEventListener('pointermove',move,{passive:false});root.addEventListener('pointerup',up);root.addEventListener('pointercancel',clean);
  return()=>{clean();root.removeEventListener('pointerdown',down);root.removeEventListener('pointermove',move);root.removeEventListener('pointerup',up);root.removeEventListener('pointercancel',clean);};
}
